async ({ shell: { execFile } }, notes: string) => {
  const run = async (p: string, a: string[], t = 60000) => { const r = await execFile(p, a, { timeoutMs: t }); if (r.code) throw new Error(`${p} ${a.join(" ")}: ${r.stderr.slice(-1500)}${r.stdout.slice(-1500)}`); return r.stdout; };
  await run("npm", ["ci"], 200000);
  const check = await execFile("npm", ["run", "check"], { timeoutMs: 250000 });
  if (check.code) return { failed: (check.stdout + check.stderr).slice(-3000) };
  const st = await run("git", ["status", "--short"]);
  await run("git", ["commit", "-am", "chore: release 2.5.5"]);
  await run("git", ["push", "-u", "origin", "chore/release-2.5.5"]);
  const pr = await run("gh", ["pr", "create", "--base", "main", "--title", "chore: release 2.5.5", "--body", notes]);
  return { st, pr };
}
